const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // Define northeastern Washington (Lynx Mountain area) and BC border region
    const lynxMountain = ee.Geometry.Point([-117.48, 48.85]); // Approximate location
    const bcBorder = ee.Geometry.Polygon([
      [[-118.5, 49.0], [-116.5, 49.0], [-116.5, 49.5], [-118.5, 49.5], [-118.5, 49.0]]
    ]);
    const washingtonArea = ee.Geometry.Polygon([
      [[-118.5, 48.5], [-116.5, 48.5], [-116.5, 49.0], [-118.5, 49.0], [-118.5, 48.5]]
    ]);

    const date = '2025-09-13';

    // Try MODIS Terra/Aqua for smoke detection
    const modisCol = ee.ImageCollection('MODIS/061/MOD09GA')
      .filterDate(date, '2025-09-14')
      .filterBounds(lynxMountain);

    console.log('MODIS images found:', modisCol.size().getInfo());

    if (modisCol.size().getInfo() === 0) {
      // Try VIIRS
      const viirsCol = ee.ImageCollection('NOAA/VIIRS/001/VNP09GA')
        .filterDate(date, '2025-09-14')
        .filterBounds(lynxMountain);

      console.log('VIIRS images found:', viirsCol.size().getInfo());

      if (viirsCol.size().getInfo() === 0) {
        console.log('No satellite imagery available for September 13, 2025');
        console.log('<answer>C1</answer>');
        return;
      }
    }

    // Try Sentinel-5P aerosol index
    const s5pCol = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_AER_AI')
      .filterDate(date, '2025-09-14')
      .filterBounds(bcBorder);

    console.log('Sentinel-5P aerosol images:', s5pCol.size().getInfo());

    if (s5pCol.size().getInfo() === 0) {
      console.log('No aerosol data available for this date');
      console.log('<answer>C1</answer>');
      return;
    }

    const aerosolImg = s5pCol.mean();

    // Check aerosol index in Washington (source)
    const washStats = aerosolImg.reduceRegion({
      reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
      geometry: washingtonArea,
      scale: 5000,
      maxPixels: 1e9
    });

    const washMean = washStats.get('absorbing_aerosol_index_mean').getInfo();
    const washCount = washStats.get('absorbing_aerosol_index_count').getInfo();

    console.log('Washington AOI - Mean aerosol index:', washMean, 'Pixels:', washCount);

    if (washCount === 0) {
      console.log('No valid pixels in Washington area');
      console.log('<answer>C2</answer>');
      return;
    }

    // Check aerosol index in BC (receptor)
    const bcStats = aerosolImg.reduceRegion({
      reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
      geometry: bcBorder,
      scale: 5000,
      maxPixels: 1e9
    });

    const bcMean = bcStats.get('absorbing_aerosol_index_mean').getInfo();
    const bcCount = bcStats.get('absorbing_aerosol_index_count').getInfo();

    console.log('BC border - Mean aerosol index:', bcMean, 'Pixels:', bcCount);

    if (bcMean === null || washMean === null) {
      console.log('Calculation failed - null results');
      console.log('<answer>C3</answer>');
      return;
    }

    // Elevated aerosol index (>1.5) suggests smoke presence
    if (bcMean > 1.5 && washMean > 1.5) {
      console.log('Elevated aerosols detected in both regions - smoke spread into BC');
      console.log('<answer>A</answer>');
    } else if (bcMean > 1.0 && washMean > 1.5) {
      console.log('Moderate aerosols in BC with elevated levels in Washington');
      console.log('<answer>A</answer>');
    } else {
      console.log('No significant smoke spread detected into BC');
      console.log('<answer>B</answer>');
    }

  } catch (error) {
    console.log('Error:', error.message);
    console.log('<answer>D</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
